WITH RankedPokemon AS (SELECT p.pok_id AS pokemon_id, p.pok_name AS pokemon_name, FLOOR((p.pok_id - 1) / 150) + 1 AS generation_id, pt.type_id AS pokemon_type, bs.b_atk AS attack, AVG(bs.b_atk) OVER (ORDER BY p.pok_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_attack, DENSE_RANK() OVER (PARTITION BY FLOOR((p.pok_id - 1) / 150) + 1, pt.type_id ORDER BY bs.b_atk DESC, p.pok_id ASC) AS attack_rank FROM pokemon p JOIN pokemon_types pt ON p.pok_id = pt.pok_id JOIN base_stats bs ON p.pok_id = bs.pok_id) SELECT generation_id, pokemon_type, attack_rank, pokemon_name, attack, ROUND(running_avg_attack, 2) AS running_avg_attack FROM RankedPokemon WHERE attack_rank <= 3 ORDER BY generation_id, pokemon_type, attack_rank;